  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The memo follows Rafael’s supplied working form and connects his particular sample-tracking work, reporting reduction, rent map and academic notebook."
    },
    "backdrop": {
      "result": "fail",
      "reason": "The leaves arrange summaries, project categories, results and testimony, but their transformations do not explain a specific work decision or mechanism beyond grouping that content."
    },
    "depth": {
      "result": "pass",
      "reason": "The sequence progresses coherently from question and context through work to evidence and a closing recruiting action."
    },
    "clipart": {
      "result": "pass",
      "reason": "The memo packet comes from Rafael’s actual working documents rather than a stock emblem of an analyst."
    },
    "honesty": {
      "result": "pass",
      "reason": "The final plan respects the corrections, distinguishes project scope and excludes unsupported claims and confidential assets."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The opening supplies his name, role, dashboard positioning, reporting-time proof and an immediate Contact link."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening uses straightforward language and a concrete five-to-two-hour reporting result."
    }
  },
  "copied_example": false,
